import{_ as s,c as i,o as a,j as n,Y as o,t as r}from"./chunks/framework.D-NV0Bun.js";const b=JSON.parse('{"title":"git-bundle | x-cmd man (git man1) | Move objects and refs by archive","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-bundle - Move objects and refs by archive","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-bundle | x-cmd man (git man1) | Move objects and refs by archive"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-bundle - Move objects and refs by archive"}]]},"headers":[],"params":{"isMan":true,"man":"git-bundle","category":"git man1","desc":"Move objects and refs by archive"},"relativePath":"git/man1/git-bundle.md","filePath":"git/man1/[man].md"}'),l={name:"git/man1/git-bundle.md"},h={class:"visually-hidden"};function p(t,e,c,d,u,g){return a(),i("div",null,[n("h1",h,r(t.$params.man),1),e[0]||(e[0]=o(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-bundle - Move objects and refs by archive</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-q </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> --quiet</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> --progress</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> --all-progress]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--all-progress-implied]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[--version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">file</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git-rev-list-args</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-q </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> --quiet]</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">fil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list-heads</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">fil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [&lt;refname&gt;...]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unbundle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--progress] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">file</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">refname</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Create, unpack, and manipulate &quot;bundle&quot; files. Bundles are used for the &quot;offline&quot; transfer of Git objects without an active &quot;server&quot; sitting on the other side of the network connection.</p><p>They can be used to create both incremental and full backups of a repository, and to relay the state of the references in one repository to another.</p><p>Git commands that fetch or otherwise &quot;read&quot; via protocols such as <strong>ssh://</strong> and <strong>https://</strong> can also operate on bundle files. It is possible <strong>git-clone</strong>(1) a new repository from a bundle, to use <strong>git-fetch</strong>(1) to fetch from one, and to list the references contained within it with <strong>git-ls-remote</strong>(1). There&#39;s no corresponding &quot;write&quot; support, i.e.a <em>git push</em> into a bundle is not supported.</p><p>See the &quot;EXAMPLES&quot; section below for examples of how to use bundles.</p><h2 id="bundle-format" tabindex="-1">BUNDLE FORMAT <a class="header-anchor" href="#bundle-format" aria-label="Permalink to &quot;BUNDLE FORMAT&quot;">​</a></h2><p>Bundles are <strong>.pack</strong> files (see <strong>git-pack-objects</strong>(1)) with a header indicating what references are contained within the bundle.</p><p>Like the packed archive format itself bundles can either be self-contained, or be created using exclusions. See the &quot;OBJECT PREREQUISITES&quot; section below.</p><p>Bundles created using revision exclusions are &quot;thin packs&quot; created using the <strong>--thin</strong> option to <strong>git-pack-objects</strong>(1), and unbundled using the <strong>--fix-thin</strong> option to <strong>git-index-pack</strong>(1).</p><p>There is no option to create a &quot;thick pack&quot; when using revision exclusions, and users should not be concerned about the difference. By using &quot;thin packs&quot;, bundles created using exclusions are smaller in size. That they&#39;re &quot;thin&quot; under the hood is merely noted here as a curiosity, and as a reference to other documentation.</p><p>See <strong>gitformat-bundle</strong>(5) for more details and the discussion of &quot;thin pack&quot; in <strong>gitformat-pack</strong>(5) for further details.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>create [options] &lt;file&gt; &lt;git-rev-list-args&gt;</p><blockquote><p>Used to create a bundle named <em>file</em>. This requires the <em>&lt;git-rev-list-args&gt;</em> arguments to define the bundle contents. <em>options</em> contains the options specific to the <em>git bundle create</em> subcommand.</p></blockquote><p>verify &lt;file&gt;</p><blockquote><p>Used to check that a bundle file is valid and will apply cleanly to the current repository. This includes checks on the bundle format itself as well as checking that the prerequisite commits exist and are fully linked in the current repository. Then, <em>git bundle</em> prints a list of missing commits, if any. Finally, information about additional capabilities, such as &quot;object filter&quot;, is printed. See &quot;Capabilities&quot; in <strong>gitformat-bundle</strong>(5) for more information. The exit code is zero for success, but will be nonzero if the bundle file is invalid.</p></blockquote><p>list-heads &lt;file&gt;</p><blockquote><p>Lists the references defined in the bundle. If followed by a list of references, only references matching those given are printed out.</p></blockquote><p>unbundle &lt;file&gt;</p><blockquote><p>Passes the objects in the bundle to <em>git index-pack</em> for storage in the repository, then prints the names of all defined references. If a list of references is given, only references matching those in the list are printed. This command is really plumbing, intended to be called only by <em>git fetch</em>.</p></blockquote><p>&lt;git-rev-list-args&gt;</p><blockquote><p>A list of arguments, acceptable to <em>git rev-parse</em> and <em>git rev-list</em> (and containing a named ref, see SPECIFYING REFERENCES below), that specifies the specific objects and references to transport. For example, <strong>master~10..master</strong> causes the current master reference to be packaged along with all objects added since its 10th ancestor commit. There is no explicit limit to the number of references and objects that may be packaged.</p></blockquote><p>[&lt;refname&gt;...]</p><blockquote><p>A list of references used to limit the references reported as available. This is principally of use to <em>git fetch</em>, which expects to receive only those references asked for and not necessarily everything in the pack (in this case, <em>git bundle</em> acts like <em>git fetch-pack</em>).</p></blockquote><p>--progress</p><blockquote><p>Progress status is reported on the standard error stream by default when it is attached to a terminal, unless -q is specified. This flag forces progress status even if the standard error stream is not directed to a terminal.</p></blockquote><p>--all-progress</p><blockquote><p>When --stdout is specified then progress report is displayed during the object count and compression phases but inhibited during the write-out phase. The reason is that in some cases the output stream is directly linked to another command which may wish to display progress status of its own as it processes incoming pack data. This flag is like --progress except that it forces progress report for the write-out phase as well even if --stdout is used.</p></blockquote><p>--all-progress-implied</p><blockquote><p>This is used to imply --all-progress whenever progress display is activated. Unlike --all-progress this flag doesn&#39;t actually force any progress display by itself.</p></blockquote><p>--version=&lt;version&gt;</p><blockquote><p>Specify the bundle version. Version 2 is the older format and can only be used with SHA-1 repositories; the newer version 3 contains capabilities that permit extensions. The default is the oldest supported format, based on the hash algorithm in use.</p></blockquote><p>-q, --quiet</p><blockquote><p>This flag makes the command not to report its progress on the standard error stream.</p></blockquote><h2 id="specifying-references" tabindex="-1">SPECIFYING REFERENCES <a class="header-anchor" href="#specifying-references" aria-label="Permalink to &quot;SPECIFYING REFERENCES&quot;">​</a></h2><p>Revisions must be accompanied by reference names to be packaged in a bundle.</p><p>More than one reference may be packaged, and more than one set of prerequisite objects can be specified. The objects packaged are those not contained in the union of the prerequisites.</p><p>The <em>git bundle create</em> command resolves the reference names for you using the same rules as <strong>git rev-parse --abbrev-ref=loose</strong>. Each prerequisite can be specified explicitly (e.g. <strong>^master~10</strong>), or implicitly (e.g. <strong>master~10..master</strong>, <strong>--since=10.days.ago master</strong>).</p><p>All of these simple cases are OK (assuming we have a &quot;master&quot; and &quot;next&quot; branch):</p><blockquote><pre><code>$ git bundle create master.bundle master
$ echo master | git bundle create master.bundle --stdin
$ git bundle create master-and-next.bundle master next
$ (echo master; echo next) | git bundle create master-and-next.bundle --stdin
</code></pre></blockquote><p>And so are these (and the same but omitted <strong>--stdin</strong> examples):</p><blockquote><pre><code>$ git bundle create recent-master.bundle master~10..master
$ git bundle create recent-updates.bundle master~10..master next~5..next
</code></pre></blockquote><p>A revision name or a range whose right-hand-side cannot be resolved to a reference is not accepted:</p><blockquote><pre><code>$ git bundle create HEAD.bundle $(git rev-parse HEAD)
fatal: Refusing to create empty bundle.
$ git bundle create master-yesterday.bundle master~10..master~5
fatal: Refusing to create empty bundle.
</code></pre></blockquote><h2 id="object-prerequisites" tabindex="-1">OBJECT PREREQUISITES <a class="header-anchor" href="#object-prerequisites" aria-label="Permalink to &quot;OBJECT PREREQUISITES&quot;">​</a></h2><p>When creating bundles it is possible to create a self-contained bundle that can be unbundled in a repository with no common history, as well as providing negative revisions to exclude objects needed in the earlier parts of the history.</p><p>Feeding a revision such as <strong>new</strong> to <strong>git bundle create</strong> will create a bundle file that contains all the objects reachable from the revision <strong>new</strong>. That bundle can be unbundled in any repository to obtain a full history that leads to the revision <strong>new</strong>:</p><blockquote><pre><code>$ git bundle create full.bundle new
</code></pre></blockquote><p>A revision range such as <strong>old..new</strong> will produce a bundle file that will require the revision <strong>old</strong> (and any objects reachable from it) to exist for the bundle to be &quot;unbundle&quot;-able:</p><blockquote><pre><code>$ git bundle create full.bundle old..new
</code></pre></blockquote><p>A self-contained bundle without any prerequisites can be extracted into anywhere, even into an empty repository, or be cloned from (i.e., <strong>new</strong>, but not <strong>old..new</strong>).</p><p>It is okay to err on the side of caution, causing the bundle file to contain objects already in the destination, as these are ignored when unpacking at the destination.</p><p>If you want to match <strong>git clone --mirror</strong>, which would include your refs such as *<em>refs/remotes/*</em> *, use <strong>--all</strong>. If you want to provide the same set of refs that a clone directly from the source repository would get, use <strong>--branches --tags</strong> for the <strong>&lt;git-rev-list-args&gt;</strong>.</p><p>The <em>git bundle verify</em> command can be used to check whether your recipient repository has the required prerequisite commits for a bundle.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>Assume you want to transfer the history from a repository R1 on machine A to another repository R2 on machine B. For whatever reason, direct connection between A and B is not allowed, but we can move data from A to B via some mechanism (CD, email, etc.). We want to update R2 with development made on the branch master in R1.</p><p>To bootstrap the process, you can first create a bundle that does not have any prerequisites. You can use a tag to remember up to what commit you last processed, in order to make it easy to later update the other repository with an incremental bundle:</p><blockquote><pre><code>machineA$ cd R1
machineA$ git bundle create file.bundle master
machineA$ git tag -f lastR2bundle master
</code></pre></blockquote><p>Then you transfer file.bundle to the target machine B. Because this bundle does not require any existing object to be extracted, you can create a new repository on machine B by cloning from it:</p><blockquote><pre><code>machineB$ git clone -b master /home/me/tmp/file.bundle R2
</code></pre></blockquote><p>This will define a remote called &quot;origin&quot; in the resulting repository that lets you fetch and pull from the bundle. The $GIT_DIR/config file in R2 will have an entry like this:</p><blockquote><pre><code>[remote &quot;origin&quot;]
    url = /home/me/tmp/file.bundle
    fetch = refs/heads/*:refs/remotes/origin/*
</code></pre></blockquote><p>To update the resulting mine.git repository, you can fetch or pull after replacing the bundle stored at /home/me/tmp/file.bundle with incremental updates.</p><p>After working some more in the original repository, you can create an incremental bundle to update the other repository:</p><blockquote><pre><code>machineA$ cd R1
machineA$ git bundle create file.bundle lastR2bundle..master
machineA$ git tag -f lastR2bundle master
</code></pre></blockquote><p>You then transfer the bundle to the other machine to replace /home/me/tmp/file.bundle, and pull from it.</p><blockquote><pre><code>machineB$ cd R2
machineB$ git pull
</code></pre></blockquote><p>If you know up to what commit the intended recipient repository should have the necessary objects, you can use that knowledge to specify the prerequisites, giving a cut-off point to limit the revisions and objects that go in the resulting bundle. The previous example used the lastR2bundle tag for this purpose, but you can use any other options that you would give to the <strong>git-log</strong>(1) command. Here are more examples:</p><p>You can use a tag that is present in both:</p><blockquote><pre><code>$ git bundle create mybundle v1.0.0..master
</code></pre></blockquote><p>You can use a prerequisite based on time:</p><blockquote><pre><code>$ git bundle create mybundle --since=10.days master
</code></pre></blockquote><p>You can use the number of commits:</p><blockquote><pre><code>$ git bundle create mybundle -10 master
</code></pre></blockquote><p>You can run <strong>git-bundle verify</strong> to see if you can extract from a bundle that was created with a prerequisite:</p><blockquote><pre><code>$ git bundle verify mybundle
</code></pre></blockquote><p>This will list what commits you must have in order to extract from the bundle and will error out if you do not have them.</p><p>A bundle from a recipient repository&#39;s point of view is just like a regular repository which it fetches or pulls from. You can, for example, map references when fetching:</p><blockquote><pre><code>$ git fetch mybundle master:localRef
</code></pre></blockquote><p>You can also see what references it offers:</p><blockquote><pre><code>$ git ls-remote mybundle
</code></pre></blockquote><h2 id="file-format" tabindex="-1">FILE FORMAT <a class="header-anchor" href="#file-format" aria-label="Permalink to &quot;FILE FORMAT&quot;">​</a></h2><p>See <strong>gitformat-bundle</strong>(5).</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,89))])}const k=s(l,[["render",p]]);export{b as __pageData,k as default};
